'use server';
import { redirect } from 'next/navigation';
import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';
import { prisma } from '@/lib/db';
import { BookingSchema } from './schema';
import { quotePrice } from '@/lib/pricing';
import { getPaymentGateway } from '@/lib/payments';

export async function createBooking(_previous: unknown, formData: FormData) {
  const parsed = BookingSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) {
    return { errors: parsed.error.flatten().fieldErrors };
  }
  const session = (await cookies()).get('session');
  if (!session) redirect('/login');
  const price = quotePrice(parsed.data.nights, parsed.data.code);
  const receipt = await getPaymentGateway().charge(price);
  const booking = await prisma.booking.create({
    data: { nights: parsed.data.nights, price, receipt: receipt.id },
  });
  revalidatePath('/bookings');
  redirect(`/bookings/${booking.id}`);
}

import { z } from 'zod';

export const BookingSchema = z.object({
  nights: z.coerce.number().min(1),
  code: z.string().optional(),
});

export async function toggleFavorite(roomId: string) {
  const response = await fetch('/api/favorites', {
    method: 'POST',
    body: JSON.stringify({ roomId }),
  });
  return response.ok;
}

import { stripeGateway } from './stripe';
import { mockGateway } from './mock';

const gateways = { stripe: stripeGateway, mock: mockGateway };

export function getPaymentGateway() {
  const key = process.env.PAYMENT_GATEWAY as keyof typeof gateways;
  return gateways[key];
}

export const mockGateway = {
  async charge(amount: number) {
    return { id: `mock-${amount}` };
  },
};

export const stripeGateway = {
  async charge(amount: number) {
    return { id: `stripe-${amount}` };
  },
};

const PROMOS: Record<string, number> = { SPRING: 0.1 };

export function quotePrice(nights: number, code?: string) {
  const base = nights * 120;
  const discount = code ? base * (PROMOS[code] ?? 0) : 0;
  return Math.max(0, base - discount);
}

export function flatPrice() {
  return 99;
}

